insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الِاسْتِخَارَةَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: "إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لِيَقُلْ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ هَذَا الْأَمْرَ - فَيُسَمِّيهِ، مَا كَانَ مِنْ شَيْءٍ - خَيْرًا لِي فِي دِينِي وَمَعَاشِي، وَعَاقِبَةِ أَمْرِي - أَوْ خَيْرًا لِي فِي عَاجِلِ أَمْرِي وَآجِلِهِ - فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي وَبَارِكْ لِي فِيهِ. وَإِنْ كُنْتَ تَعْلَمُ - يَقُولُ مِثْلَ مَا قَالَ فِي الْمَرَّةِ الْأُولَى - وَإِنْ كَانَ شَرًّا لِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُمَا كَانَ، ثُمَّ رَضِّنِي بِهِ". (خ,د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) ഖുർആനിലെ ഒരു സൂറത്ത് പഠിപ്പിക്കുന്നതു പോലെ ഞങ്ങൾക്ക് ഇസ്തിഖാറ(നന്മയെത്തേടിയുള്ള നിസ്കാരം)ത്തിന്റെ വചനങ്ങൾ പഠിപ്പിച്ചുതന്നു; നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരു കാര്യത്തിൽ (അത് നന്മയോ തിന്മയോ എന്ന്) പ്രയാസത്തിലായാൽ അയാൾ നിർബന്ധ നിസ്കാരമല്ലാത്ത നിലക്ക് രണ്ട് റക്അത്ത് നിസ്കരിച്ച് ഇപ്രകാരം പറയട്ടെ; അല്ലാഹുവെ, ഞാൻ നിന്റെ ജ്ഞാനം മുൻനിർത്തി നന്മയെ തേടുന്നു. നിന്റെ ഉന്നതമായ കഴിവു കൊണ്ട് ഞാൻ കഴിവ് തേടുന്നു. നിന്റെ മഹോന്നതമായ ഔദാര്യം ഞാൻ കാംക്ഷിക്കുന്നു. നീ എല്ലാം കഴിയുന്നവനും ഞാൻ ഒന്നിനും കഴിയാത്തവനുമാണ്. നീ എല്ലാം അറിയുന്നവനും ഞാൻ അജ്ഞനുമാണ്. നീയാകട്ടെ അദൃശ്യങ്ങൾ അറിയുന്നവനാണ്. അല്ലാഹുവെ, ഈ കാര്യത്തെക്കുറിച്ച് നീ അറിയുന്നവനാകയാൽ - ആ കാര്യം എടുത്ത് പറയുന്നു - അത് എനിക്കും എന്റെ ദീനിന്നും ജീവിതത്തിനും എന്റെ കാര്യങ്ങളുടെ പരിണിതിക്കും ഉത്തമമാണെങ്കിൽ - അത് ഇപ്പോഴും പിന്നീടും നന്മയാണെങ്കിൽ - എന്റെ കഴിവിന് വിധേയമാക്കുകയും എനിക്കത് എളുപ്പമാക്കുകയും എനിക്കതിൽ അനുഗ്രഹം നൽകുകയും ചെയ്യേണമേ; ഇനി നിന്റെ അറിവിൽ പ്രസ്തുത കാര്യം - ആദ്യ പ്രാവശ്യം പറഞ്ഞതുപോലെ പറയുന്നു - എനിക്ക് ദോഷകരമാണെങ്കിൽ എന്നിൽ നിന്ന് അതിനെ നീ മാറ്റിത്തരികയും അതിൽ നിന്ന് എന്നെ മുക്തനാക്കുകയും ചെയ്യേണമേ, ഏതൊരിടത്തും എനിക്ക് നീ നന്മയെ വിധിക്കേണമേ, അതിൽ എന്നെ നീ സംതൃപ്തനാക്കുകയും ചെയ്യേണമേ." (ബു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 691, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَنْ كَانَتْ لَهُ حَاجَةٌ إِلَى اللهِ، أَوْ إِلَى أَحَدٍ مِنْ خَلْقِهِ، فَلْيَتَوَضَّأْ وَلْيُصَلِّ رَكْعَتَيْنِ، ثُمَّ لِيَقُلْ: لَا إِلَهَ إِلَّا اللهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ. اللَّهُمَّ إِنِّي أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ. أَسْأَلُكَ أَلَّا تَدَعَ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا لِي. ثُمَّ يَسْأَلُ اللهَ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ مَا شَاءَ، فَإِنَّهُ يُقَدَّرُ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫൽ അസ്ലമീ(റ): നബി(സ) ഞങ്ങളുടെ അടുത്തുവന്ന് പറഞ്ഞു: "വല്ലവനും അല്ലാഹുവിലേക്കോ അവന്റെ വല്ല സൃഷ്ടികളിലേക്കോ ആവശ്യക്കാരനായാൽ നന്നായി വുദു ചെയ്ത് രണ്ട് റക്അത്ത് നിസ്കരിച്ച് ഇപ്രകാരം പറയട്ടെ: ഔദാര്യവാനും വിട്ടുവീഴ്ച ചെയ്യുന്നവനുമായ അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല. ഉന്നതമായ അർശിന്റെ രക്ഷിതാവായ അല്ലാഹു എത്ര പരിശുദ്ധൻ! ലോകരക്ഷിതാവായ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. നിന്റെ കാരുണ്യം ലഭിക്കാനുള്ള കാര്യങ്ങളെയും പാപമോചനം ലഭിക്കാനുള്ള മാർഗ്ഗങ്ങളെയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. എല്ലാ നന്മയിൽ നിന്നുമുള്ള സൗഭാഗ്യവും ഞാൻ ചോദിക്കുന്നു. എല്ലാ കുറ്റങ്ങളിൽ നിന്നും നിന്നോട് ഞാൻ രക്ഷ തേടുന്നു. നീ പൊറുക്കാത്ത ഒരു പാപവും, നീ അകറ്റാത്ത ഒരു ദുഃഖവും എന്നിൽ നീ ശേഷിപ്പിക്കരുതേ! നിനക്ക് തൃപ്തിയുള്ള ഒരാവശ്യവും എനിക്ക് സാധ്യമാക്കാതെ നീ ഉപേക്ഷിക്കരുതേ. പിന്നെ ഇഹപര ആവശ്യങ്ങൾ അല്ലാഹുവിനോട് അവൻ ചോദിക്കട്ടെ. അത് കണക്കിലെടുക്കപ്പെടും." (ജ)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى الْأَسْلَمِيِّ', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫൽ അസ്ലമീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 691, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عُثْمَانَ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا ضَرِيرَ الْبَصَرِ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ادْعُ اللهَ لِي أَنْ يُعَافِيَنِي. فَقَالَ: "إِنْ شِئْتَ أَخَّرْتُ لَكَ وَهُوَ خَيْرٌ، وَإِنْ شِئْتَ دَعَوْتُ". فَقَالَ: ادْعُهْ. فَأَمَرَهُ أَنْ يَتَوَضَّأَ فَيُحْسِنَ وُضُوءَهُ، وَيُصَلِّيَ رَكْعَتَيْنِ، وَيَدْعُوَ بِهَذَا الدُّعَاءِ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِمُحَمَّدٍ نَبِيِّ الرَّحْمَةِ. يَا مُحَمَّدُ، إِنِّي قَدْ تَوَجَّهْتُ بِكَ إِلَى رَبِّي فِي حَاجَتِي هَذِهِ لِتُقْضَى. اللَّهُمَّ شَفِّعْهُ فِيَّ". (ت,جه)', 'ഉസ്മാനുബ്നു ഹുനൈഫ്(റ): കണ്ണിന് അസുഖമുള്ള ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: എന്റെ അസുഖം ഭേദമാക്കാൻ താങ്കൾ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുക. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നിനക്ക് ഞാൻ (പ്രാർത്ഥന) പിന്തിക്കും. അതാണ് നിനക്ക് നല്ലത്. നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നിനക്ക് ഞാൻ പ്രാർത്ഥിക്കാം." അദ്ദേഹം പറഞ്ഞു: താങ്കൾ അല്ലാഹുവോട് ദുആ ചെയ്യുക. അപ്പോൾ നബി(സ) അയാളോട് നന്നായി വുദൂ ചെയ്ത് രണ്ട് റക്അത്ത് നിസ്കരിച്ച് ഇപ്രകാരം പ്രാർത്ഥിക്കാൻ കൽപിച്ചു: "അല്ലാഹുവേ, ''കാരുണ്യത്തിന്റെ നബിയായ മുഹമ്മദ് നബി(സ)യെ മുൻനിർത്തി ഞാൻ നിന്നോട് ചോദിക്കുന്നു. മുഹമ്മദ് നബി(സ)യേ, എന്റെ ആവശ്യം സാധ്യമാവാൻ വേണ്ടി ഞാൻ താങ്കളെ മുൻനിർത്തി എന്റെ നാഥനോട് ചോദിക്കുന്നു. അല്ലാഹുവേ, എന്റെ കാര്യത്തിൽ മുഹമ്മദ് നബി(സ)യെ നീ ശുപാർശകനാക്കിയാലും." (തു,ജ)', 'عُثْمَانَ بْنِ حُنَيْفٍ', 'ഉസ്മാനുബ്നു ഹുനൈഫ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أَصَرَّ مَنِ اسْتَغْفَرَ، وَإِنْ عَادَ فِي الْيَوْمِ سَبْعِينَ مَرَّةً". (د,ت)', 'അബൂബക്കർ സീദ്ദീഖ്(റ): നബി(സ) പറഞ്ഞു: "തെറ്റ് ചെയ്ത ശേഷം പാപമോചനം തേടിയവൻ തെറ്റിൽ ഉറച്ച് നിന്നവനാവുകയില്ല. ഒരു ദിവസം എഴുപതു പ്രാവശ്യം അതാവർത്തിച്ചിട്ടുണ്ടെങ്കിലും ശരി." (ദ,തു)', 'أَبِي بَكْرٍ الصِّدِّيقِ', 'അബൂബക്കർ സീദ്ദീഖ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ الْأَغَرِّ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ، وَكَانَتْ لَهُ صُحْبَةٌ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ لَيُغَانُ عَلَى قَلْبِي، وَإِنِّي لَأَسْتَغْفِرُ اللهَ فِي كُلِّ يَوْمٍ مِائَةَ مَرَّةٍ". (م,د)', 'അഗർറിൽ മുസനിയ്യി(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം എന്റെ ഹൃദയം (ചിലപ്പോൾ ദൈവ സ്മരണയിൽ നിന്ന്) അശ്രദ്ധമാവും. (അതുകൊണ്ട് തന്നെ) എല്ലാ ദിവസവും നൂറ് പ്രാവശ്യം ഞാൻ അല്ലാഹുവിനോട് പാപമോചനം തേടുന്നു." (മു,ദ)', 'الْأَغَرِّ الْمُزَنِيِّ', 'അഗർറിൽ മുസനിയ്യി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنْ كُنَّا لَنَعُدُّ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَجْلِسِ الْوَاحِدِ مِائَةَ مَرَّةٍ: "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ". (د,ن,جه)', 'ഇബ്നു ഉമർ(റ): നബി(സ)യുടെ ഓരോ മജ്ലിസിൽ നിന്നും ഞങ്ങൾ നൂറുവട്ടം ഇപ്രകാരം എണ്ണുമായിരുന്നു; "എന്റെ നാഥാ, എനിക്ക് പൊറുത്തു തരേണമേ, എനിക്ക് നീ പാപമോചനം നൽകേണമേ, നിശ്ചയം നീ ഏറെ പൊറുക്കുന്നവനും കാരുണ്യവാനുമാകുന്നു.¹" (ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', '¹. പാപ സുരക്ഷിതനാണെങ്കിലും അല്ലാഹുവിനോടുള്ള തന്റെ വിനയവും നന്ദിയും മൂലമായിരുന്നു ഇങ്ങനെ പ്രാർത്ഥിച്ചിരുന്നത്. അനുയായികൾക്ക് ശിക്ഷണം നൽകാനും.', null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي يَسَارٍ زَيْدِ بْنِ بُولَا - مَوْلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ قَالَ: أَسْتَغْفِرُ اللهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ، غُفِرَ لَهُ وَإِنْ كَانَ قَدْ فَرَّ مِنَ الزَّحْفِ". (د,ت)', 'നബി(സ)യുടെ ഭൃത്യനായ അബൂയസാർ സൈദുബ്നു ബൂല(റ): നബി(സ) ഇപ്രകാരം പറയുന്നതായി അദ്ദേഹം കേട്ടു: "സർവ്വ നിയന്താവും എന്നെന്നും ജീവിക്കുന്നവനുമായ അല്ലാഹുവിനോട് ഞാൻ പാപമോചനം തേടുന്നു. അവനല്ലാതെ ഒരു ആരാധ്യനുമില്ല, ഞാൻ അവനിലേക്ക് പശ്ചാതപിച്ച് മടങ്ങുന്നു. എന്ന് ഒരാൾ പറഞ്ഞാൽ അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെടും. അവൻ യുദ്ധമുഖത്ത് നിന്ന് ഓടിയവനാണെങ്കിലും." (ദ,തു)', 'أَبِي يَسَارٍ زَيْدِ بْنِ بُولَا - مَوْلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ -', 'നബി(സ)യുടെ ഭൃത്യനായ അബൂയസാർ സൈദുബ്നു ബൂല(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 693, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَزِمَ الِاسْتِغْفَارَ جَعَلَ اللهُ لَهُ مِنْ كُلِّ ضِيقٍ مَخْرَجًا، وَمِنْ كُلِّ هَمٍّ فَرَجًا، وَرَزَقَهُ مِنْ حَيْثُ لَا يَحْتَسِبُ". (د,ن,جه)', 'ഇബ്നു അബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു "ആരെങ്കിലും പാപമോചനം തേടൽ (ഇസ്തിഗ്ഫാർ) പതിവാക്കിയാൽ അല്ലാഹു അവന് എല്ലാ പ്രയാസങ്ങളിൽ നിന്നും മോചനം നൽകും. എല്ലാ ദുഃഖങ്ങളിൽ നിന്നും മുക്തി നൽകും. അവൻ പോലും നിനച്ചിരിക്കാത്ത വഴികളിലൂടെ അവന് വിഭവങ്ങൾ നൽകും." (ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 693, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ وَقَدْ سُئِلَ: أَيُّ دَعْوَةٍ كَانَ يَدْعُو بِهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَكْثَرُ؟ قَالَ: كَانَ أَكْثَرُ دَعْوَةٍ يَدْعُو بِهَا: "اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ". وَكَانَ أَنَسٌ إِذَا أَرَادَ أَنْ يَدْعُوَ بِدَعْوَةٍ دَعَا بِهَا، وَإِذَا أَرَادَ أَنْ يَدْعُوَ بِدُعَاءٍ، دَعَا بِهَا فِيهَا. (ق,د,ن)', 'അനസ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: ഏതു പ്രാർഥനയാണ് നബി(സ) അധികമായി പ്രാർത്ഥിച്ചിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: "അല്ലാഹുവെ, ഞങ്ങളുടെ നാഥാ, ഞങ്ങൾക്ക് നീ ഐഹിക ജീവിതത്തിൽ നന്മ നൽകേണമേ, പരലോകത്തും നന്മ നൽകേണമേ, ഞങ്ങളെ നരക ശിക്ഷയിൽ നിന്ന് രക്ഷിക്കേണമേ." എന്നാണ് തിരുനബി(സ) കൂടുതലായി പ്രാർത്ഥിച്ചു കൊണ്ടിരുന്നത്. അനസ്(റ) പ്രാർത്ഥിക്കാൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ ഈ വചനങ്ങൾ പ്രാർത്ഥിക്കും. അദ്ദേഹം (മറ്റു വല്ലതും) പ്രാർത്ഥിക്കാനുദ്ദേശിച്ചാൽ ഈ വാചകം അടങ്ങുന്നതാണ് പ്രാർത്ഥിച്ചിരുന്നത്. (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 693, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ اللهَ الشَّهَادَةَ صَادِقًا بَلَّغَهُ اللهُ مَنَازِلَ الشُّهَدَاءِ، وَإِنْ مَاتَ عَلَى فِرَاشِهِ". (م,د,ت,ن,جه)', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ): നബി(സ) പറഞ്ഞു "ആരെങ്കിലും സത്യസന്ധമായി അല്ലാഹുവിനോട് രക്തസാക്ഷിത്വം ചോദിച്ചാൽ അല്ലാഹു അവനെ രക്തസാക്ഷികളുടെ പദവിയിലെത്തിക്കും, അയാൾ തന്റെ വിരിപ്പിൽ കിടന്ന് മരിച്ചാലും ശരി." (മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ حُنَيْفٍ', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 693, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ رَجُلًا إِذَا سَمِعْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا نَفَعَنِي اللهُ مِنْهُ بِمَا شَاءَ أَنْ يَنْفَعَنِي، وَإِذَا حَدَّثَنِي أَحَدٌ مِنْ أَصْحَابِهِ اسْتَحْلَفْتُهُ، فَإِذَا حَلَفَ لِي صَدَّقْتُهُ، قَالَ: وَحَدَّثَنِي أَبُو بَكْرٍ - وَصَدَقَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ - قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ عَبْدٍ يُذْنِبُ ذَنْبًا فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللهَ، إِلَّا غَفَرَ اللهُ لَهُ". ثُمَّ قَرَأَ هَذِهِ الْآيَةَ: {وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللهَ} [آل عمران: ١٣٥] إِلَى آخِرِ الْآيَةِ. (د,ت,ن,جه)', 'അലി(റ): നബി(സ) എന്തെങ്കിലും പറയുന്നതായി ഞാൻ കേട്ടാൽ, അല്ലാഹു അവൻ ഉദ്ദേശിക്കുന്നത്രയും അതെനിക്ക് പ്രയോജനപ്പെടുത്തിത്തരാറുണ്ടായിരുന്നു. സ്വഹാബാക്കളിൽ ആരെങ്കിലും എന്നോട് വല്ല ഹദീസും പറഞ്ഞാൽ ഞാൻ അയാളോട് സത്യം ചെയ്യാൻ ആവശ്യപ്പെടും. അയാൾ സത്യം ചെയ്താൽ ഞാനത് വിശ്വസിക്കുകയും ചെയ്യും. അബൂബക്കർ(റ) എന്നോട് പറഞ്ഞു: അദ്ദേഹം സത്യമാണ് പറഞ്ഞത്. നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു. "വല്ല തെറ്റും ചെയ്ത ഏതൊരു അടിമയും നന്നായി ശുദ്ധി വരുത്തുകയും രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും തുടർന്ന് അല്ലാഹുവിനോട് പാപമോചനം തേടുകയും ചെയ്താൽ അല്ലാഹു അവന് പൊറുത്തു കൊടുക്കാതിരിക്കില്ല." ശേഷം ''വല്ല നീചവൃത്തിയും ചെയ്യുകയോ സ്വന്തത്തോട് അക്രമം കാണിക്കുകയോ ചെയ്തപോയാൽ അല്ലാഹുവിനെ സ്മരിക്കുകയും അങ്ങനെ പാപമോചനത്തിനായി പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നവർക്ക് പാപങ്ങൾ പൊറുക്കുന്നവൻ അല്ലാഹുവല്ലാതെ മറ്റാരുണ്ട്?'' (ആലു ഇംറാൻ 135) എന്ന സൂക്തം നബി(സ) പൂർണ്ണമായി പാരായണം ചെയ്തു. (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], 'آل عمران: ١٣٥', null, 693, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخَذَ بِيَدِهِ وَقَالَ: "يَا مُعَاذُ، وَاللهِ إِنِّي لَأُحِبُّكَ، وَاللهِ إِنِّي لَأُحِبُّكَ. أُوصِيكَ يَا مُعَاذُ: لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُولُ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ". (د)', 'മുആദുബ്നു ജബൽ(റ): അദ്ദേഹത്തിന്റെ കയ്യിൽ പിടിച്ചുകൊണ്ട് നബി(സ) പറഞ്ഞു: "മുആദ്, അല്ലാഹുവാണെ! ഞാൻ നിന്നെ ഇഷ്ടപ്പെടുന്നു, അല്ലാഹുവാണെ! ഞാൻ നിന്നെ ഇഷ്ടപ്പെടുന്നു. മുആദ്, ഞാൻ നിന്നെ ഉപദേശിക്കുകയാണ്: അല്ലാഹുവേ, നിന്റെ സ്മരണയിലും, നിനക്ക് നന്ദി ചെയ്യുന്നതിലും, നിനക്ക് നല്ല നിലയിൽ ആരാധിക്കുന്നതിലും എന്നെ നീ സഹായിക്കേണമേ. എന്ന് നീ എല്ലാ നിസ്കാരശേഷവും പറയുക." (ദ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْرَأَ بِالْمُعَوِّذَاتِ دُبُرَ كُلِّ صَلَاةٍ. (د,ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): എല്ലാ നിസ്കാര ശേഷവും മുഅവ്വിദാത്ത് (സൂറഃ അൽ ഫലഖ്, അന്നാസ്) ചൊല്ലാൻ നബി(സ) എന്നോട് കൽപിച്ചിരിക്കുന്നു. (ദ,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): മൂന്ന് പ്രാവശ്യം ദുആ ചെയ്യലും, മൂന്നു പ്രാവശ്യം പൊറുക്കലിനെ തേടലും നബി(സ)ക്ക് പ്രിയങ്കരമായിരുന്നു. (ദ,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُعَلِّمُكِ كَلِمَاتٍ تَقُولِينَهُنَّ عِنْدَ الْكَرْبِ، أَوْ فِي الْكَرْبِ: أَللَّهُ، أَللَّهُ رَبِّي، لَا أُشْرِكُ بِهِ شَيْئًا". (د,ن,جه)', 'അസ്മാഅ് ബിൻത് ഉമൈസ്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "പ്രയാസമുണ്ടാകുമ്പോൾ പറയാനുള്ള പദങ്ങൾ ഞാൻ നിനക്ക് അറിയിച്ചു തരട്ടെയോ? ''അല്ലാഹ്! അല്ലാഹു എന്റെ നാഥനാണ്, ഞാൻ നിന്നിൽ യാതൊന്നിനെയും പങ്കുചേർക്കില്ല'' എന്നാണത്." (ദ,ന,ജ)', 'أَسْمَاءَ بِنْتِ عُمَيْسٍ', 'അസ്മാഅ് ബിൻത് ഉമൈസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ: رَضِيتُ بِاللهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ رَسُولًا، وَجَبَتْ لَهُ الْجَنَّةُ". (م,د,ن)', 'അബൂസഈദിൽ ഖുദ്രീ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ റബ്ബായും, ഇസ്ലാമിനെ മതമായും, മുഹമ്മദ്(സ)യെ റസൂലായും ഞാൻ തൃപ്തിപ്പെട്ടു എന്ന് ആരെങ്കിലും പറഞ്ഞാൽ അവന്ന് സ്വർഗ്ഗം നിർബന്ധമായി." (മു,ദ,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രീ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى عَلَيَّ وَاحِدَةً، صَلَّى اللهُ عَلَيْهِ عَشْرًا". (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവനും എന്റെ മേൽ ഒരു സ്വലാത്ത് (അനുഗ്രഹത്തിനുള്ള പ്രാർത്ഥന) ചൊല്ലിയാൽ അല്ലാഹു അവന്റെ മേൽ പത്ത് സ്വലാത്ത് (അനുഗ്രഹം) ചെയ്യും." (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَوْسِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ، فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ، فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ". قَالَ: فَقَالُوا: يَا رَسُولَ اللهِ، وَكَيْفَ تُعْرَضُ صَلَاتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ قَالَ: يَقُولُونَ: بَلِيتَ، قَالَ: "إِنَّ اللهَ تَبَارَكَ وَتَعَالَى حَرَّمَ عَلَى الْأَرْضِ أَجْسَادَ الْأَنْبِيَاءِ صَلَّى اللهُ عَلَيْهِمْ". (د,ن,جه)', 'ഔസുബ്നു ഔസ്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, നിങ്ങളുടെ ദിവസങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠം വെള്ളിയാഴ്ചയാണ്. അതിനാൽ അന്ന് നിങ്ങൾ എന്റെമേൽ സ്വലാത്ത് വർദ്ധിപ്പിക്കുക. തീർച്ചയായും നിങ്ങളുടെ സ്വലാത്തിനെ എനിക്ക് വെളിവാക്കപ്പെടുന്നതാണ്." നിവേദകൻ പറഞ്ഞു: അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! താങ്കൾ മരിച്ച് മണ്ണായിരിക്കെ എങ്ങനെയാണ് ഞങ്ങളുടെ സ്വലാത്തിനെ വെളിവാക്കപ്പെടുക? നബി(സ) പറഞ്ഞു: "തീർച്ചയായും അനുഗ്രഹീതനും ഉന്നതനുമായ അല്ലാഹു നബിമാരുടെ ശരീരങ്ങൾ ഭൂമിക്ക് ഹറാമാക്കിയിരിക്കുന്നു." (ദ,ന,ജ)', 'أَوْسِ بْنِ أَوْسٍ', 'ഔസുബ്നു ഔസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 694, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَدْعُوا عَلَى أَنْفُسِكُمْ، وَلَا تَدْعُوا عَلَى أَوْلَادِكُمْ، وَلَا تَدْعُوا عَلَى خَدَمِكُمْ، وَلَا تَدْعُوا عَلَى أَمْوَالِكُمْ، لَا تُوَافِقُوا مِنَ اللهِ تَبَارَكَ وَتَعَالَى سَاعَةَ نَيْلٍ فِيهَا عَطَاءٌ، فَيَسْتَجِيبَ لَكُمْ". (م,د)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങൾക്കെതിരായും, നിങ്ങളുടെ മക്കൾക്കെതിരായും, നിങ്ങളുടെ സേവകർക്കെതിരായും, നിങ്ങളുടെ സമ്പത്തിനെതിരായും പ്രാർത്ഥിക്കരുത്. നിങ്ങൾക്ക് ഉത്തരം നൽകപ്പെടുന്ന ഒരു സന്ദർഭവുമായി ഈ പ്രാർത്ഥന ഒത്ത് വരാതിരിക്കാൻ. അങ്ങനെ ഒത്ത് വന്നാൽ പ്രാർത്ഥനക്ക് ഉത്തരം ലഭിച്ചേക്കും." (മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً قَالَتْ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: صَلِّ عَلَيَّ وَعَلَى زَوْجِي، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَّى اللهُ عَلَيْكِ وَعَلَى زَوْجِكِ". (د,ت,ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഒരു സ്ത്രീ റസൂലി(സ)നോട് പറഞ്ഞു: എന്റെയും എന്റെ ഭർത്താവിന്റെയും മേൽ താങ്കൾ അനുഗ്രഹത്തിന് പ്രാർത്ഥിച്ചാലും. നബി(സ) പറഞ്ഞു: "നിന്റെയും നിന്റെ ഭർത്താവിന്റെയും മേൽ അല്ലാഹുവിന്റെ അനുഗ്രഹമുണ്ടാകട്ടെ!." (ദ,തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا دَعَا الرَّجُلُ لِأَخِيهِ بِظَهْرِ الْغَيْبِ قَالَتِ الْمَلَائِكَةُ: آمِينَ، وَلَكَ بِمِثْلٍ". (م,د)', 'അബുദ്ദർദാഇ(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ഒരാൾ തന്റെ സഹോദരനു വേണ്ടി അവന്റെ അഭാവത്തിൽ നടത്തുന്ന പ്രാർത്ഥനക്ക് മലക്കുകൾ ''ആമീൻ'' എന്നും, ''അപ്രകാരം നിനക്കും ഉണ്ടാവട്ടെ!'' എന്നും പറയുന്നതാണ്." (മു,ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഇ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَسْرَعَ الدُّعَاءِ إِجَابَةً دَعْوَةُ غَائِبٍ لِغَائِبٍ". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാളുടെ അഭാവത്തിൽ അയാൾക്കു വേണ്ടി നടത്തുന്ന പ്രാർത്ഥനയാണ് ഏറ്റവും വേഗത്തിൽ ഉത്തരം ലഭിക്കുന്ന പ്രാർത്ഥന." (ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لَا شَكَّ فِيهِنَّ: دَعْوَةُ الْوَالِدِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْمَظْلُومِ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്സംശയം മൂന്ന് പ്രാർത്ഥനക്ക് ഉത്തരം ലഭിക്കും. (സന്താനങ്ങൾക്കു വേണ്ടിയുള്ള) പിതാവിന്റെ പ്രാർത്ഥന, യാത്രക്കാരന്റെ പ്രാർത്ഥന, മർദ്ദിതന്റെ പ്രാർത്ഥന എന്നിവയാണവ." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ مِنْ خَمْسٍ: مِنَ الْجُبْنِ وَالْبُخْلِ، وَسُوءِ الْعُمُرِ، وَفِتْنَةِ الصَّدْرِ، وَعَذَابِ الْقَبْرِ. (د,ن,جه)', 'ഉമറുബ്നു ഖത്താബ്(റ): ഭീരുത്വം, പിശുക്ക്, വിഷമകരമായ വാർദ്ധക്യം, ഹൃദയത്തിന്റെ ഉപദ്രവം (ചീത്ത വിചാരങ്ങൾ), ഖബറിലെ ശിക്ഷ എന്നീ അഞ്ച് കാര്യങ്ങളിൽ നിന്നും നബി(സ) അഭയം തേടിയിരുന്നു. (ദ,ന,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നു ഖത്താബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ، وَالْبُخْلِ، وَالْهَرَمِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". وَفِي رِوَايَةٍ: كُنْتُ أَخْدُمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكُنْتُ أَسْمَعُهُ كَثِيرًا يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ، وَالْحُزْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ". (ق,د,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറയുന്നതായി ഞാൻ ധാരാളം കേട്ടു: "അല്ലാഹുവേ, ദൗർബല്യത്തിൽ നിന്നും, അലസതയിൽ നിന്നും, ഭീരുത്വത്തിൽ നിന്നും, പിശുക്കിൽ നിന്നും, വാർദ്ധക്യത്തിന്റെ അവശതയിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു. ഖബറിലെ ശിക്ഷയിൽ നിന്നും, മരണത്തിലെയും ജീവിതത്തിലെയും ഉപദ്രവത്തിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു." മറ്റൊരു റിപ്പോർട്ടിൽ: ഞാൻ നബി(സ)ക്ക് സേവനം ചെയ്തിരുന്നു. തിരുമേനി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ പലപ്പോഴും കേട്ടിരുന്നു: "അല്ലാഹുവെ! സന്താപത്തിൽ നിന്നും, ഖേദത്തിൽ നിന്നും, കടത്തിന്റെ ഭാരത്തിൽ നിന്നും, ആളുകളുടെ മേൽകോയ്മയിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു". (ബു,മു,ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=28 and h.hadith_no=25), 1, 'وَفِي رِوَايَةٍ: كُنْتُ أَخْدُمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكُنْتُ أَسْمَعُهُ كَثِيرًا يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ، وَالْحُزْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ". (ق,د,ن)', 'മറ്റൊരു നിവേദനിൽ: ഞാൻ നബി(സ)ക്ക് സേവനം ചെയ്തിരുന്നു. തിരുമേനി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ പലപ്പോഴും കേട്ടിരുന്നു: "അല്ലാഹുവെ! സന്താപത്തിൽ നിന്നും, ഖേദത്തിൽ നിന്നും, കടത്തിന്റെ ഭാരത്തിൽ നിന്നും, ആളുകളുടെ മേൽകോയ്മയിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു". (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ هَذَا الدُّعَاءَ كَمَا يُعَلِّمُهُمُ السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". (م,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഖുർആനിലെ ഒരു അധ്യായം പഠിപ്പിക്കുംപോലെ നബി(സ) ഈ പ്രാർത്ഥന അവരെ പഠിപ്പിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ! നരകശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു. ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും, മസീഹുദ്ദജ്ജാലിന്റെ കുഴപ്പത്തിൽ നിന്നും, ജീവിതത്തിലെയും മരണത്തിലെയും കുഴപ്പത്തിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു." (മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو بِهَؤُلَاءِ الْكَلِمَاتِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ، وَعَذَابِ النَّارِ، وَمِنْ شَرِّ الْغِنَى وَالْفَقْرِ". (ق,د,ت,ن)', 'ആഇശ(റ): നബി(സ) ഈ വാചകങ്ങൾ പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു. "അല്ലാഹുവേ! നരകത്തിന്റെ ഉപദ്രവത്തിൽ നിന്നും, നരക ശിക്ഷയിൽ നിന്നും, ദാരിദ്രത്തിന്റെയും ഐശ്വര്യത്തിന്റെയും കെടുതികളിൽ നിന്നും നിന്നോട് ഞാൻ രക്ഷ തേടുന്നു". (ബു,മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ، وَالْقِلَّةِ، وَالذِّلَّةِ، وَأَعُوذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ദാരിദ്ര്യത്തിൽ നിന്നും, ഇല്ലായ്മയിൽ നിന്നും, നിന്ദ്യതയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു. അപ്രകാരം അക്രമിക്കുന്നതിൽ നിന്നും, അക്രമിക്കപ്പെടുന്നതിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ مِنْ دُعَاءِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحْوِيلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سُخْطِكَ". (م,د)', 'ഇബ്നു ഉമർ(റ): നബി(സ)യുടെ പ്രാർത്ഥനയിൽ പെട്ടതായിരുന്നു. "അല്ലാഹുവേ, നിന്റെ അനുഗ്രഹം നീങ്ങിപ്പോവുന്നതിൽ നിന്നും, നീ നൽകിയ സൗഖ്യം തെറ്റിപ്പോകുന്നതിൽ നിന്നും, നിന്റെ പെട്ടെന്നുള്ള ശിക്ഷയിൽ നിന്നും, നിന്റെ എല്ലാ കോപങ്ങളിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു." (മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشِّقَاقِ، وَالنِّفَاقِ، وَسُوءِ الْأَخْلَاقِ". (د,ن)', 'അബൂഹൂറൈറ(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ഭിന്നിപ്പിൽ നിന്നും, കാപട്യത്തിൽ നിന്നും ദുഃസ്വഭാവങ്ങളിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു". (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹൂറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ". (د,ن)', 'അബുഹുറൈറ(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, വിശപ്പിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു. നിശ്ചയം അതേറ്റവും ദുഷിച്ച കൂടെകിടപ്പുകാരനത്രെ, അപ്രകാരം വഞ്ചനയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു. നിശ്ചയം അത് ഏറ്റവും ദുഷിച്ച അടിവസ്ത്രമാകുന്നു." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْأَرْبَعِ: مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دُعَاءٍ لَا يُسْمَعُ". (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ നാലു കാര്യങ്ങളിൽ നിന്നും ഞാൻ നിന്നോട് അഭയം തേടുന്നു. ഉപകാരപ്രദമല്ലാത്ത വിജ്ഞാനം, ഭയഭക്തിയില്ലാത്ത ഹൃദയം, മതിവരാത്ത മനസ്സ്, ഉത്തരം ലഭിക്കാത്ത പ്രാർത്ഥന എന്നിവയിൽ നിന്ന്." (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ صَلَاةٍ لَا تَنْفَعُ". (د)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ഉപകാരപ്രദമല്ലാത്ത നിസ്കാരത്തിൽ നിന്നും നിന്നിൽ ഞാൻ അഭയം തേടുന്നു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ فَرْوَةَ بْنِ نَوْفَلٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا: عَمَّا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُو بِهِ، قَالَتْ: كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ". (م,د,ن,جه)', 'ഫർവതുബ്നു നൗഫലുൽ അശ്ജഈ(റ): നബി(സ)യുടെ പ്രാർത്ഥനയെക്കുറിച്ച് ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചപ്പോൾ അവർ പറഞ്ഞു: നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ ഞാൻ പ്രവർത്തിച്ചവയുടെ ഉപദ്രവത്തിൽ നിന്നും പ്രവർത്തിക്കാത്തവയുടെ ഉപദ്രവത്തിൽ നിന്നും നിന്നിൽ ഞാൻ അഭയം തേടുന്നു." (മു,ദ,ന,ജ)', 'فَرْوَةَ بْنِ نَوْفَلٍ الْأَشْجَعِيِّ', 'ഫർവതുബ്നു നൗഫലുൽ അശ്ജഈ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ شَكَلِ بْنِ حُمَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، عَلِّمْنِي دُعَاءً. قَالَ: "قُلْ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي". (د,ت,ن)', 'ശക്ലുബ്നു ഹമീദ്(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, എനിക്കൊരു പ്രാർത്ഥന പഠിപ്പിച്ചു തന്നാലും. നബി(സ) പറഞ്ഞു: "നീ പറയുക; അല്ലാഹുവേ! എന്റെ ചെവിയുടെയും, എന്റെ കണ്ണിന്റെയും, എന്റെ നാവിന്റെയും, എന്റെ ഹൃദയത്തിന്റെയും, എന്റെ ബീജത്തിന്റെയും ദോഷത്തിൽ നിന്ന് നിന്നിൽ ഞാൻ അഭയം തേടുന്നു." (ദ,തു,ന)', 'شَكَلِ بْنِ حُمَيْدٍ', 'ശക്ലുബ്നു ഹമീദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي الْيَسَرِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الْغَرَقِ، وَالْحَرَقِ، وَالْهَرَمِ. وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا". وَفِي رِوَايَةٍ زَادَ فِيهِ: "وَالْغَمِّ". (د,ن)', 'അബൂൽയസർ(റ): നബി(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, കെട്ടിടം തകരുന്നതിൽ നിന്നും, കീഴ്പോട്ട് വീഴുന്നതിൽ നിന്നും മുങ്ങുന്നതിൽ നിന്നും, അഗ്നി ബാധയിൽ നിന്നും, വാർദ്ധക്യത്തിന്റെ ക്ഷീണത്തിൽ നിന്നും നിന്നോട് ഞാൻ അഭയം തേടുന്നു. മരണ വേളയിൽ പിശാച് ബാധിക്കുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ അഭയം തേടുന്നു. നിന്റെ മാർഗ്ഗത്തിലുള്ള സമരത്തിൽ നിന്ന് പുറംതിരിഞ്ഞോടുന്ന നിലയിൽ മരണപ്പെടുന്നതിൽ നിന്നും വിഷം ബാധിച്ച് മരണപ്പെടുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ അഭയം തേടുന്നു." മറ്റൊരു റിപ്പോർട്ടിൽ: "ദുഃഖത്തിൽ നിന്നും." (ദ,ന)', 'أَبِي الْيَسَرِ', 'അബൂൽയസർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=28 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ زَادَ فِيهِ: "وَالْغَمِّ". (د,ن)', 'മറ്റൊരു നിവേദനിൽ: "ദുഃഖത്തിൽ നിന്നും." (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَرَصِ، وَالْجُنُونِ، وَالْجُذَامِ، وَمِنْ سَيِّئِ الْأَسْقَامِ". (د,ن)', 'അനസ്(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, വെള്ളപ്പാണ്ട്, ഭ്രാന്ത്, കുഷ്ഠം, മറ്റ് ദുർവ്യാധികൾ എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നിൽ അഭയം തേടുന്നു." (ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ يُقَالُ لَهُ أَبُو أُمَامَةَ فَقَالَ: "يَا أَبَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ". قَالَ: هُمُومٌ لَزِمَتْنِي وَدُيُونٌ يَا رَسُولَ اللهِ. قَالَ: "أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ اللهُ عَزَّ وَجَلَّ هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟" قَالَ: قُلْتُ: بَلَى يَا رَسُولَ اللهِ، قَالَ: "قُلْ إِذَا أَصْبَحْتَ وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ". قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللهُ عَزَّ وَجَلَّ هَمِّي، وَقَضَى عَنِّي دَيْنِي. (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഒരിക്കൽ നബി(സ) പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ അബൂഉമാമ എന്ന അൻസാരികളിൽപ്പെട്ട ഒരാൾ അവിടെയുണ്ടായിരുന്നു. നബി(സ) ചോദിച്ചു: "അബൂഉമാമ, നിസ്കാരത്തിന്റെ സമയത്തല്ലാതെ നീ പള്ളിയിലിരിക്കുന്നുവല്ലോ, എന്തുപറ്റി?" അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബിയെ, കടവും വിഷമവും തന്നെ കാരണം. നബി(സ) ചോദിച്ചു: "താങ്കളുടെ വിഷമം കുറയ്ക്കാനും നിന്റെ കടം വീട്ടിത്തരാനും ഉതകുന്ന വിധമുള്ള വചനങ്ങൾ നിനക്ക് ഞാൻ പഠിപ്പിച്ചു തരട്ടെയോ?" അദ്ദേഹം പറയുന്നു: ഞാൻ പറഞ്ഞു: അതെ നബിയെ! നബി(സ) പറഞ്ഞു: "പ്രഭാതമായാലും പ്രദോഷമായാലും നീ പറയുക; അല്ലാഹുവേ! അസ്വസ്ഥതയിൽ നിന്നും, ദുഃഖത്തിൽ നിന്നും, ദൗർബ്ബല്യത്തിൽ നിന്നും, ആലസ്യത്തിൽ നിന്നും, ഭീരുത്വത്തിൽ നിന്നും, പിശുക്കിൽ നിന്നും, കട ഭാരത്തിൽ നിന്നും, ആളുകളുടെ അടിച്ചമർത്തലിൽ നിന്നും നിന്നോട് ഞാൻ അഭയം തേടുന്നു." അദ്ദേഹം പറഞ്ഞു. ഞാൻ അപ്രകാരം ചെയ്തു. അപ്പോൾ പ്രതാപവാനും മഹാനുമായ അല്ലാഹു എന്റെ വിഷമം നീക്കിത്തരികയും കടം വീട്ടിത്തരികയും ചെയ്തു. (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=28 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
